function observe(obj, onChange, path = [], cache = new WeakMap()) {
  if (cache.has(obj)) return cache.get(obj);
  const proxy = new Proxy(obj, {
    get(target, key, receiver) {
      const value = Reflect.get(target, key, receiver);
      if (typeof key === "string" && value !== null && typeof value === "object") {
        return observe(value, onChange, [...path, key], cache);
      }
      return value;
    },
    set(target, key, value, receiver) {
      const old = target[key];
      const ok = Reflect.set(target, key, value, receiver);
      if (ok && !Object.is(old, value)) onChange([...path, String(key)], old, value);
      return ok;
    },
    deleteProperty(target, key) {
      const had = Object.prototype.hasOwnProperty.call(target, key);
      const old = target[key];
      const ok = Reflect.deleteProperty(target, key);
      if (ok && had) onChange([...path, String(key)], old, undefined);
      return ok;
    },
  });
  cache.set(obj, proxy);
  return proxy;
}

