function recorder() {
  const log = [];
  return { log, fn: (path, from, to) => log.push([path.join("."), from, to]) };
}

test("top-level changes", () => {
  const r = recorder();
  const s = observe({ count: 1 }, r.fn);
  s.count = 2;
  s.count = 2;
  s.name = "x";
  delete s.name;
  checkEq(r.log, [["count", 1, 2], ["name", undefined, "x"], ["name", "x", undefined]]);
});

test("nested objects and arrays", () => {
  const r = recorder();
  const s = observe({ settings: { theme: "dark" }, items: [] }, r.fn);
  s.settings.theme = "light";
  s.items.push("a");
  checkEq(r.log, [["settings.theme", "dark", "light"], ["items.0", undefined, "a"]]);
});

test("the same nested proxy each time", () => {
  const s = observe({ inner: { a: 1 } }, () => {});
  check(s.inner === s.inner, "reading inner twice should give the same proxy");
  checkEq(s.inner.a, 1);
});

